      "example": "Betreff: Hund mit ins Büro nehmen\n\nSehr geehrte Damen und Herren,\n\nich möchte meinen Hund mit ins Büro nehmen, weil ich nächste Woche niemanden für seine Betreuung habe. Ich möchte ihn am Montag und am Dienstag mitnehmen. Mein Hund ist klein, ruhig und freundlich. Er bleibt in seinem Körbchen und stört die anderen Mitarbeiter nicht. Darf ich ihn an diesen beiden Tagen mitbringen? Vielen Dank für Ihre Antwort.\n\nIn der Mittagspause gehe ich mit ihm spazieren. Sein Futter und eine Decke bringe ich selbst mit. Wenn es ein Problem gibt, suche ich eine andere Betreuung.\n\nMit freundlichen Grüßen\n[Ihr Name]",
