      "example": "Betreff: Monatskarte verloren\n\nSehr geehrte Damen und Herren,\n\nich habe meine Monatskarte verloren. Wahrscheinlich ist sie beim Aussteigen aus meiner Tasche gefallen. Das ist gestern gegen 17 Uhr in der Straßenbahn Linie 1 passiert. Mein Name steht auf der Karte. Könnten Sie bitte im Fundbüro nachsehen? Ich möchte die Karte gern abholen. Vielen Dank für Ihre Hilfe.\n\nIch brauche die Karte täglich für meinen Weg zur Arbeit. Falls sie gefunden wird, schreiben Sie mir bitte eine kurze Nachricht. Ich kann morgen nach der Arbeit ins Fundbüro kommen.\n\nMit freundlichen Grüßen\n[Ihr Name]",
