      "example": "Betreff: Kamera im Hotel vergessen\n\nSehr geehrte Damen und Herren,\n\nletzte Woche war ich im Urlaub in Wien. Der Urlaub war sehr schön, und ich habe in Ihrem Hotel übernachtet. Leider habe ich meine schwarze Kamera im Zimmer vergessen. Sie lag auf dem Tisch neben dem Bett. Bitte suchen Sie nach der Kamera und schicken Sie sie mir per Post. Ich bezahle die Versandkosten. Vielen Dank für Ihre Hilfe.\n\nAuf der Kamera sind viele Fotos von meiner Reise. Diese Bilder sind mir sehr wichtig. Meine Adresse schicke ich Ihnen gern, sobald Sie die Kamera gefunden haben. Bitte antworten Sie mir kurz.\n\nMit freundlichen Grüßen\n[Ihr Name]",
