      "example": "Betreff: Überfüllter Kindergartenbus\n\nSehr geehrte Damen und Herren,\n\nmeine Tochter fährt jeden Morgen mit Ihrem Bus zum Kindergarten. Leider ist der Bus oft überfüllt. Gestern konnte sie nicht einsteigen, weil kein Platz mehr frei war. Dadurch kam sie zu spät. Bitte schicken Sie einen größeren Bus oder bieten Sie eine zusätzliche Fahrt an. Ich hoffe, dass Sie bald eine Lösung finden. Vielen Dank.\n\nIch muss morgens selbst zur Arbeit und kann meine Tochter nicht jeden Tag bringen. Deshalb brauchen wir einen zuverlässigen Bus. Bitte informieren Sie mich, wie meine Tochter morgen zum Kindergarten kommen kann.\n\nMit freundlichen Grüßen\n[Ihr Name]",
