      "example": "Betreff: Haarschnitt des Sohnes\n\nSehr geehrte Damen und Herren,\n\nmein Sohn war gestern um 14 Uhr in Ihrem Friseursalon. Leider sind seine Haare viel kürzer geworden, als wir gewünscht hatten. An einigen Stellen ist der Haarschnitt auch ungleichmäßig. Ich bin deshalb nicht zufrieden. Können Sie den Haarschnitt bitte kostenlos verbessern? Ich möchte mit meinem Sohn am Freitag noch einmal vorbeikommen.\n\nMein Sohn ist über seine neue Frisur sehr traurig. Vor dem Schneiden hatten wir erklärt, dass nur die Spitzen gekürzt werden sollen. Bitte teilen Sie mir mit, ob der vorgeschlagene Termin möglich ist.\n\nMit freundlichen Grüßen\n[Ihr Name]",
