      "example": "Betreff: Mantel im Restaurant vergessen\n\nSehr geehrte Damen und Herren,\n\nich war gestern Abend in Ihrem Restaurant und habe meinen Mantel dort vergessen. Wahrscheinlich hängt er noch an der Garderobe. Er ist dunkelblau und hat die Größe M. In einer Tasche liegt ein Schlüssel. Bitte bewahren Sie den Mantel für mich auf. Kann ich ihn heute gegen 17 Uhr abholen? Vielen Dank für Ihre Hilfe.\n\nWir saßen an einem Tisch direkt neben dem Fenster. Ich habe das Restaurant gegen 21 Uhr verlassen. Falls Sie den Mantel finden, senden Sie mir bitte eine kurze Nachricht per E-Mail.\n\nMit freundlichen Grüßen\n[Ihr Name]",
