      "example": "Betreff: Anmeldung zum Fotokurs\n\nSehr geehrte Damen und Herren,\n\nich möchte mich für Ihren Fotokurs anmelden, weil ich gern fotografiere und bessere Fotos machen möchte. Leider habe ich noch keine eigene Kamera. Kann ich während des Kurses eine Kamera ausleihen? Wann beginnt der nächste Kurs, und wie viel kostet er? Ich habe am Wochenende Zeit. Vielen Dank für Ihre Informationen.\n\nBisher mache ich meine Fotos nur mit dem Handy. Besonders gern fotografiere ich Menschen und Landschaften. Ich möchte lernen, wie ich das Licht besser nutzen kann und worauf ich beim Fotografieren achten soll.\n\nMit freundlichen Grüßen\n[Ihr Name]",
