      "exampleArabic": "الموضوع: إلغاء عقد موقف السيارة\n\nالسيدة فاغنر المحترمة،\n\nأرغب في إلغاء عقد موقف سيارتي لأنني بعت السيارة. يرجى إخباري حتى متى يجب أن أستمر في دفع الإيجار. يهتم جاري السيد شالتس بالموقف ويرغب في استئجاره بعدي. هل يمكنكم التواصل معه؟ يرجى تأكيد إنهاء العقد لي كتابيًا.\n\nلذلك لن أحتاج إلى الموقف مستقبلًا. يسكن جاري في المبنى نفسه، ويمكنه استئجاره قريبًا. متى ينبغي أن أعيد إليكم مفتاح الكراج؟\n\nمع خالص التحيات\n[اسمك]",
