      "example": "Betreff: Taschen im Treppenhaus\n\nSehr geehrte Damen und Herren,\n\nSie haben mich über die Taschen vor meiner Tür informiert. Ich möchte Ihnen erklären, dass diese Taschen nicht mir gehören. Ich werde meine Nachbarn fragen, wem sie gehören. Bitte informieren Sie auch die anderen Bewohner und sorgen Sie dafür, dass das Treppenhaus frei bleibt. Vielen Dank für Ihre Hilfe und Ihr Verständnis.\n\nMir ist wichtig, dass alle Bewohner die Treppe sicher benutzen können. Die Taschen stehen seit gestern dort. Wenn ich den Besitzer finde, bitte ich ihn, sie sofort aus dem Treppenhaus zu entfernen.\n\nMit freundlichen Grüßen\n[Ihr Name]",
