      "example": "Betreff: Kinderbetreuung bei Children’s City\n\nSehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige gelesen. Ich arbeite viel und brauche deshalb einen Betreuungsplatz für mein Kind. Mein Kind ist fünf Jahre alt. Ich benötige die Betreuung von Montag bis Freitag am Nachmittag. Haben Sie einen freien Platz? Bitte informieren Sie mich über Ihre Öffnungszeiten und die Kosten. Vielen Dank für Ihre Antwort.\n\nMeine Arbeitszeit endet meistens erst um 17 Uhr. In dieser Zeit kann niemand aus meiner Familie auf mein Kind aufpassen. Ich möchte Ihre Einrichtung gern besuchen und die Mitarbeiter persönlich kennenlernen.\n\nMit freundlichen Grüßen\n[Ihr Name]",
      "category": "Familie",
      "note": "الملف مقصوص بعد «Grund: Warum brauchen Sie die». النقطتان الثانية والثالثة غير ظاهرتين. لا يمكن استخدام هذه المهمة كنموذج امتحاني مكتمل حتى توفير الجزء الناقص.",
