      "originalIntro": "Du bist in Urlaub und deine Nachbarin hat sich um deinen Garten gekümmert",
      "introArabic": "أنت في إجازة واعتنت جارتك بحديقتك.",
      "bodyWordCount": 77,
      "taskIntro": "Sie sind im Urlaub. Ihre Nachbarin hat sich um Ihren Garten gekümmert. Schreiben Sie ihr eine E-Mail.",
      "sourceNotice": ""
