      "exampleArabic": "الموضوع: طلبية أونلاين من شركة تكنكس\n\nالسادة المحترمون،\n\nأكتب إليكم بشأن طلبيتي. قبل شهر طلبت من تكنكس سماعات بسعر 49 يورو. للأسف لم يصل الطرد بعد. أنا خارج البلاد منذ أسبوعين. هل يمكنكم إخباري بمكان الطرد؟ يرجى توصيله بعد عودتي. شكرًا على مساعدتكم.\n\nسأعود إلى المنزل يوم الاثنين القادم. أستطيع استلام الطرد شخصيًا ابتداءً من الثلاثاء. إذا لم يكن التوصيل ممكنًا حينها، فيرجى إخباري بموعد آخر.\n\nمع خالص التحيات\n[اسمك]",
